J=pathlib.Path(sys.argv[1]); EXP=pathlib.Path(sys.argv[2]); P=pathlib.Path(sys.argv[3]); ASSET=pathlib.Path(sys.argv[4])
files={
'net/minecraft/block/state/IBlockState.java': '''package net.minecraft.block.state; import net.minecraft.block.Block; public class IBlockState { public final Block b; public final int m; public IBlockState(Block b,int m){this.b=b;this.m=m;} public Block getBlock(){return b;} }''',
'net/minecraft/block/Block.java': '''package net.minecraft.block; import net.minecraft.block.state.IBlockState; public class Block { public final IBlockState[] states=new IBlockState[16]; public boolean tile; public Block(){for(int i=0;i<16;i++)states[i]=new IBlockState(this,i);} public IBlockState getDefaultState(){return states[0];} public IBlockState getStateFromMeta(int m){return states[m];} public int getMetaFromState(IBlockState s){return s.m;} public boolean hasTileEntity(IBlockState s){return tile;} }''',
'net/minecraft/init/Blocks.java': '''package net.minecraft.init; import net.minecraft.block.Block; public class Blocks {public static final Block AIR=new Block(), STONE=new Block(), BEDROCK=new Block(), GRASS=new Block(), DIRT=new Block(), GRAVEL=new Block(), IRON_ORE=new Block(), WATER=new Block(), LOG=new Block(), CHEST=new Block(); static {CHEST.tile=true;} }''',
'net/minecraft/world/chunk/ChunkPrimer.java': '''package net.minecraft.world.chunk; import net.minecraft.block.state.IBlockState; import net.minecraft.init.Blocks; public class ChunkPrimer { public final IBlockState[] a=new IBlockState[65536]; public int reads,writes,failAfter=-1; public boolean failRead; public ChunkPrimer(){for(int x=0;x<16;x++)for(int z=0;z<16;z++)for(int y=0;y<256;y++)a[(x*16+z)*256+y]=(y==0?Blocks.BEDROCK:y<=64?Blocks.STONE:Blocks.AIR).getDefaultState();} int idx(int x,int y,int z){if(x<0||x>15||z<0||z>15||y<0||y>255)throw new AssertionError("outside primer");return (x*16+z)*256+y;} public IBlockState getBlockState(int x,int y,int z){reads++;if(failRead)throw new IllegalStateException();return a[idx(x,y,z)];} public void setBlockState(int x,int y,int z,IBlockState s){if(writes==failAfter)throw new IllegalStateException();a[idx(x,y,z)]=s;writes++;} public void put(int x,int y,int z,IBlockState s){a[idx(x,y,z)]=s;} }''',
'net/minecraftforge/event/terraingen/ChunkGeneratorEvent.java': '''package net.minecraftforge.event.terraingen; import net.minecraft.world.chunk.ChunkPrimer; public class ChunkGeneratorEvent {public static class ReplaceBiomeBlocks {final int x,z; final ChunkPrimer p; public ReplaceBiomeBlocks(int x,int z,ChunkPrimer p){this.x=x;this.z=z;this.p=p;} public int getX(){return x;} public int getZ(){return z;} public ChunkPrimer getPrimer(){return p;} }}''',
'com/mikael8367/nexustech/worldgen/PrimerTest.java': '''package com.mikael8367.nexustech.worldgen;
import java.nio.file.*;import java.io.*;import java.util.*;import net.minecraft.block.Block;import net.minecraft.block.state.IBlockState;import net.minecraft.init.Blocks;import net.minecraft.world.chunk.ChunkPrimer;import net.minecraftforge.event.terraingen.ChunkGeneratorEvent.ReplaceBiomeBlocks;
public class PrimerTest {
 static int checks; static void ck(boolean b,String s){checks++;if(!b)throw new AssertionError(s);} static NoGlassSchematic sc; static long seed=42; static int cx; static NoGlassPlan.Candidate c;
 static NoGlassPrimerExperiment.Report run(ChunkPrimer p){return NoGlassPrimerExperiment.apply(new ReplaceBiomeBlocks(cx,-3,p),seed,sc);} static void rejected(ChunkPrimer p,NoGlassPrimerExperiment.Status s){NoGlassPrimerExperiment.Report r=run(p);ck(r.status==s,"expected "+s+" got "+r.status);ck(p.writes==0 && r.completedWrites==0,"no writes on reject");}
 static Block block(int id){switch(id){case 0:return Blocks.AIR;case 1:return Blocks.STONE;case 2:return Blocks.GRASS;case 3:return Blocks.DIRT;case 13:return Blocks.GRAVEL;case 15:return Blocks.IRON_ORE;default:throw new AssertionError();}}
 public static void main(String[] args)throws Exception {sc=NoGlassSchematic.load(new ByteArrayInputStream(Base64.getMimeDecoder().decode(Files.readAllBytes(Paths.get(args[0])))));cx=-1000;while((c=NoGlassPlan.select(seed,cx,-3))==null)cx++;
 ChunkPrimer p=new ChunkPrimer();IBlockState[] before=p.a.clone(); NoGlassPrimerExperiment.Report r=run(p);ck(r.status==NoGlassPrimerExperiment.Status.WRITTEN_TO_PRIMER && r.completedWrites==640 && p.writes==640,"success"); int gravel=0,air=0;
 for(int x=0;x<16;x++)for(int z=0;z<16;z++)for(int y=0;y<256;y++){IBlockState s=p.getBlockState(x,y,z);if(x>=c.x && x<c.x+10 && z>=c.z && z<c.z+8 && y>=62 && y<70){int sx=x-c.x,sy=y-62,sz=z-c.z,id=sc.id(sx,sy,sz);ck(s==block(id).getStateFromMeta(sc.meta(sx,sy,sz)),"schematic mismatch");if(id==13)gravel++;if(id==0)air++;}else ck(s==before[(x*16+z)*256+y],"outside changed");}ck(gravel==12&&air==325,"palette");
 ChunkPrimer water=new ChunkPrimer();water.put(c.x-2,80,c.z-2,Blocks.WATER.getDefaultState());rejected(water,NoGlassPrimerExperiment.Status.UNSAFE_TERRAIN); ChunkPrimer tree=new ChunkPrimer();tree.put(c.x,65,c.z,Blocks.LOG.getDefaultState());rejected(tree,NoGlassPrimerExperiment.Status.UNSAFE_TERRAIN);ChunkPrimer tile=new ChunkPrimer();tile.put(c.x,64,c.z,Blocks.CHEST.getDefaultState());rejected(tile,NoGlassPrimerExperiment.Status.UNSAFE_TERRAIN);ChunkPrimer mod=new ChunkPrimer();mod.put(c.x,64,c.z,new Block().getDefaultState());rejected(mod,NoGlassPrimerExperiment.Status.UNSAFE_TERRAIN);ChunkPrimer meta=new ChunkPrimer();meta.put(c.x,63,c.z,Blocks.STONE.getStateFromMeta(1));rejected(meta,NoGlassPrimerExperiment.Status.UNSAFE_TERRAIN);ChunkPrimer hole=new ChunkPrimer();hole.put(c.x,63,c.z,Blocks.AIR.getDefaultState());rejected(hole,NoGlassPrimerExperiment.Status.UNSAFE_TERRAIN);ChunkPrimer sloped=new ChunkPrimer();sloped.put(c.x,65,c.z,Blocks.STONE.getDefaultState());rejected(sloped,NoGlassPrimerExperiment.Status.UNSAFE_TERRAIN);
 ChunkPrimer read=new ChunkPrimer();read.failRead=true;rejected(read,NoGlassPrimerExperiment.Status.READ_FAILED); ChunkPrimer part=new ChunkPrimer();part.failAfter=37;r=run(part);ck(r.status==NoGlassPrimerExperiment.Status.READY_WRITE_FAILED_PARTIAL && r.completedWrites==37 && part.writes==37,"partial write explicit");
 ck(NoGlassPrimerExperiment.apply(null,seed,sc).status==NoGlassPrimerExperiment.Status.INVALID,"null event");ck(NoGlassPrimerExperiment.apply(new ReplaceBiomeBlocks(cx,-3,null),seed,sc).status==NoGlassPrimerExperiment.Status.INVALID,"null primer");ck(NoGlassPrimerExperiment.apply(new ReplaceBiomeBlocks(Integer.MAX_VALUE,0,new ChunkPrimer()),seed,sc).status==NoGlassPrimerExperiment.Status.INVALID,"overflow");
 int ux=0;while(NoGlassPlan.select(seed,ux,0)!=null)ux++;ChunkPrimer un=new ChunkPrimer();r=NoGlassPrimerExperiment.apply(new ReplaceBiomeBlocks(ux,0,un),seed,sc);ck(r.status==NoGlassPrimerExperiment.Status.NOT_SELECTED && un.reads==0 && un.writes==0,"not selected");
 for(int h:new int[]{2,3,4,250,251}){ChunkPrimer q=new ChunkPrimer();for(int x=0;x<16;x++)for(int z=0;z<16;z++)for(int y=1;y<256;y++)q.put(x,y,z,(y<=h?Blocks.STONE:Blocks.AIR).getDefaultState());r=run(q);ck(r.status==(h>=4&&h<=250?NoGlassPrimerExperiment.Status.WRITTEN_TO_PRIMER:NoGlassPrimerExperiment.Status.UNSAFE_TERRAIN),"height "+h);}
 int oldcx=cx;NoGlassPlan.Candidate oldc=c;int count=0; for(int k=-1000;k<1000 && count<50;k++){NoGlassPlan.Candidate t=NoGlassPlan.select(seed,k,-3);if(t==null)continue;cx=k;c=t;ChunkPrimer q=new ChunkPrimer();r=run(q);ck(r.status==NoGlassPrimerExperiment.Status.WRITTEN_TO_PRIMER&&q.writes==640,"candidate "+k);count++;}ck(count==50,"sample");cx=oldcx;c=oldc;
 System.out.println("PASS fake Forge primer: "+checks+" assertions, exact 640 states, 65536-cell footprint check, 50 candidates, 12 gravel, 325 air"); }
}'''
}
